async function throwIfResNotOk(
  res: Response,
  request?: { method?: string; url?: string },
) {
  if (!res.ok) {
    const text = (await res.text()) || res.statusText;
    const error = new Error(`${res.status}: ${text}`);
    await reportHandledError({
      error,
      request,
      response: { status_code: res.status },
    });
    throw error;
  }
}

async function parseJsonResponse<T>(
  res: Response,
  request?: { method?: string; url?: string },
): Promise<T> {
  const contentType = res.headers.get("content-type")?.toLowerCase() ?? "";

  if (!contentType.includes("application/json")) {
    const text = await res.text();
    const preview = text.slice(0, 200) || res.statusText || "Empty response body";
    const error = new Error(
      `Expected JSON response but received ${contentType || "unknown content type"}: ${preview}`,
    );
    await reportHandledError({
      error,
      request,
      response: { status_code: res.status },
    });
    throw error;
  }

  try {
    return (await res.json()) as T;
  } catch (error) {
    await reportHandledError({
      error,
      request,
      response: { status_code: res.status },
    });
    throw error;
  }
}

export async function apiRequest(
  method: string,
  url: string,
  data?: unknown | undefined,
): Promise<Response> {
  const headers: Record<string, string> = data ? { "Content-Type": "application/json" } : {};

  // Add auth token if available
  const token = getAuthToken();
  if (token) {
    headers["Authorization"] = `Bearer ${token}`;
  }

  try {
    const res = await fetch(url, {
      method,
      headers,
      body: data ? JSON.stringify(data) : undefined,
      credentials: "include",
    });

    await throwIfResNotOk(res, { method, url });
    return res;
  } catch (error) {
    await reportHandledError({
      error,
      request: { method, url },
    });
    throw error;
  }
}

type UnauthorizedBehavior = "returnNull" | "throw";
export const getQueryFn: <T>(options: {
  on401: UnauthorizedBehavior;
}) => QueryFunction<T> =
  ({ on401: unauthorizedBehavior }) =>
  async ({ queryKey }) => {
    const url = queryKey.join("/") as string;
    try {
      const res = await fetch(url, {
        credentials: "include",
      });

      if (unauthorizedBehavior === "returnNull" && res.status === 401) {
        return null;
      }

      await throwIfResNotOk(res, { method: "GET", url });
      return await parseJsonResponse<T>(res, { method: "GET", url });
    } catch (error) {
      await reportHandledError({
        error,
        request: { method: "GET", url },
      });
      throw error;
    }
  };

